// Contrast to map
pets.Map(a => toSeq(a.Split(','))); // => [[cat, dog], [fish, bird]]

var shouted = from pet  in pets
              from name in toSeq(pet.Split(','))
              select name.ToUpper();
// => [CAT, DOG, FISH, BIRD]

