// example 2: get the first item in list
// first :: [A] -> A
A First<A>(A[] xs) => xs[0];
First([42]); // => 42
// First(Array.Empty<int>());  IndexOutOfRangeException

// example 3: repeat function N times
// times :: int -> (int -> ()) -> ()
void Times(int n, Action<int> f)
{
    if (n == 0) return;
    f(n);
    Times(n - 1, f);
}
Times(3, Console.WriteLine);
